// The Couple brand mark and wordmark, drawn natively.
//
// Geometry mirrors design/logo/couple-wordmark.svg (one SVG unit = one unit
// here): the mark is the two track colors as an interlocked chain link, bbox
// x 21..205, y 41..159; "UPLE" follows as outlined glyphs from
// CoupleWordmarkGlyphs.swift (generated by design/logo/outline-uple.py from
// the bundled Nunito, so no font is needed at render time). The over/under
// gaps are inverse clips, so the mark renders on any background.

import SwiftUI

/// Shared drawing of the interlocked C+O in wordmark coordinates.
enum CoupleMarkGeometry {
    static let minX: CGFloat = 21
    static let maxX: CGFloat = 205
    static let minY: CGFloat = 41
    static let height: CGFloat = 118

    /// Draws the mark into `ctx`, mapping wordmark units through `map`
    /// (which must be a uniform scale `s` plus translation).
    static func draw(in ctx: GraphicsContext, scale s: CGFloat, map: (CGFloat, CGFloat) -> CGPoint) {
        let cC = map(80, 100)
        let cO = map(146, 100)
        let r = 45.0 * s
        let main = StrokeStyle(lineWidth: 28.0 * s, lineCap: .round)

        // Teal C: open ring, mouth facing the O (arc runs the long way around).
        var cArc = Path()
        cArc.addArc(center: cC, radius: r, startAngle: .degrees(-33), endAngle: .degrees(33), clockwise: true)

        // Cut in the C where the amber band passes over its upper arm.
        var cutTeal = Path()
        cutTeal.addArc(center: cO, radius: r, startAngle: .degrees(-100), endAngle: .degrees(-170), clockwise: true)
        let cutTealArea = cutTeal.strokedPath(StrokeStyle(lineWidth: 44.0 * s, lineCap: .butt))

        // Cut in the O where the C's lower arm (tip included) passes over it.
        var cutAmber = Path()
        cutAmber.addArc(center: cC, radius: r, startAngle: .degrees(33), endAngle: .degrees(95), clockwise: false)
        let cutAmberArea = cutAmber.strokedPath(StrokeStyle(lineWidth: 44.0 * s, lineCap: .round))

        let oCircle = Path(ellipseIn: CGRect(x: cO.x - r, y: cO.y - r, width: 2 * r, height: 2 * r))

        ctx.drawLayer { layer in
            layer.clip(to: cutTealArea, options: .inverse)
            layer.stroke(cArc, with: .color(Theme.camera), style: main)
        }
        ctx.drawLayer { layer in
            layer.clip(to: cutAmberArea, options: .inverse)
            layer.stroke(oCircle, with: .color(Theme.external), style: main)
        }
    }
}

/// The C+O mark alone. In a lockup with text, size `height` to ~1.04x the
/// cap height of the adjacent text.
struct CoupleMark: View {
    var height: CGFloat

    var body: some View {
        Canvas { ctx, size in
            let s = size.height / CoupleMarkGeometry.height
            CoupleMarkGeometry.draw(in: ctx, scale: s) { x, y in
                CGPoint(x: (x - CoupleMarkGeometry.minX) * s, y: (y - CoupleMarkGeometry.minY) * s)
            }
        }
        .frame(width: height * (CoupleMarkGeometry.maxX - CoupleMarkGeometry.minX) / CoupleMarkGeometry.height, height: height)
        .accessibilityHidden(true)
    }
}

/// The full "COUPLE" lockup: mark + outlined UPLE, identical to the SVG.
/// `height` is the mark's height; the glyphs' cap height follows (~0.96x).
struct CoupleWordmark: View {
    var height: CGFloat
    var ink: Color = Theme.textPrimary

    private var unitsWide: CGFloat { CoupleWordmarkGlyphs.endX - CoupleMarkGeometry.minX }

    var body: some View {
        Canvas { ctx, size in
            let s = size.height / CoupleMarkGeometry.height
            func map(_ x: CGFloat, _ y: CGFloat) -> CGPoint {
                CGPoint(x: (x - CoupleMarkGeometry.minX) * s, y: (y - CoupleMarkGeometry.minY) * s)
            }
            CoupleMarkGeometry.draw(in: ctx, scale: s, map: map)
            let origin = map(0, 0)
            let glyphs = CoupleWordmarkGlyphs.path()
                .applying(CGAffineTransform(a: s, b: 0, c: 0, d: s, tx: origin.x, ty: origin.y))
            ctx.fill(glyphs, with: .color(ink))
        }
        .frame(width: height * unitsWide / CoupleMarkGeometry.height, height: height)
        .accessibilityElement(children: .ignore)
        .accessibilityLabel("Couple")
    }
}
